(function () {
  if (window.location.hostname !== 'www.arcads.ai') { return; }
  try {
    if (sessionStorage.getItem('apf_redirected')) { return; }
    sessionStorage.setItem('apf_redirected', '1');
  } catch (e) {}
  try {
    var KEY = '44e5a6f3152249aae19ed3e4cad65ea';
    var name = 'AMP_' + KEY.slice(0, 10) + '=';
    var parts = document.cookie ? document.cookie.split('; ') : [];
    var raw = null;
    for (var i = 0; i < parts.length; i++) {
      if (parts[i].indexOf(name) === 0) { raw = parts[i].slice(name.length); }
    }
    if (raw && navigator.sendBeacon) {
      var who = JSON.parse(decodeURIComponent(atob(raw)));
      if (who && who.deviceId) {
        var event = {
          device_id: who.deviceId,
          session_id: who.sessionId,
          event_type: '$impression',
          event_properties: { flag_key: 'meta-paid-funnel', variant: 'treatment' },
          time: Date.now()
        };
        if (who.userId) { event.user_id = who.userId; }
        navigator.sendBeacon('https://api2.amplitude.com/2/httpapi', JSON.stringify({ api_key: KEY, events: [event] }));
      }
    }
  } catch (e) {}
  window.location.replace('https://app.arcads.ai/go?ab_funnel=test');
})();
